import sys


def main():
    data = sys.stdin.buffer.read()
    sums = {}
    get = sums.get
    lines = data.split(b"\n")
    for line in lines[1:]:
        if not line:
            continue
        parts = line.split(b",")
        if len(parts) < 3:
            continue
        cat = parts[1].rstrip(b"\r").decode()
        v = float(parts[2])
        sums[cat] = get(cat, 0.0) + v
    out = []
    for cat in sorted(sums):
        out.append("%s,%.2f" % (cat, sums[cat]))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

