import sys
from collections import defaultdict


def main():
    lines = sys.stdin.buffer.read().split(b"\n")
    sums = defaultdict(float)
    for line in lines[1:]:
        if not line:
            continue
        p = line.split(b",")
        if len(p) < 3:
            continue
        sums[p[1]] += float(p[2])
    out = [k.decode() + ",%.2f" % sums[k] for k in sorted(sums)]
    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
